  'room.ideas.desc':
    '想法日记和头脑风暴，自由画布上的10种概念图格式（思维导图、树状图、时间线、循环图、金字塔图、韦恩图等），以及8种决策图（利弊分析、力场分析、SWOT分析、艾森豪威尔矩阵、决策树、分级列表、加权决策矩阵和鱼骨图），手绘或用AI都行。',
  'room.metas.desc': '整个家里你给自己定下的事：目标列表连同它们的子目标和步骤，AI为每个目标提出的计划（带日期的阶段会变成真正的子目标），还有让一切在时间轴上占据各自时段的日程。',
