  'tut.app-computo--formulario.titulo': '公式手册',
  'tut.app-computo--formulario.resumen': '公式手册是你自己的公式本。数学、物理和化学的公式已经预先加载，但它们并不是独立的目录：都是你的公式，可以像自己写的一样编辑、移动或删除。',
