  'ideas.tipoDesc.tier': '从S到D的分级行，用来给任何事物排名。',
  'ideas.tipo.matriz': '决策矩阵',
  'ideas.tipoDesc.matriz': '按你真正在意的标准为多个选项打分。',
  'ideas.guia.matriz': '每个标准根据对你的重要程度加权（1-5分），每个选项在该标准上打1-5分。总分是得分乘以权重，所以在你不在乎的标准上表现出色也赢不了。',
  'ideas.matriz.criterio': '标准',
  'ideas.matriz.opcion': '选项',
  'ideas.matriz.peso': '权重',
  'ideas.matriz.pesoAyuda': '这个标准对你有多重要（1-5）',
  'ideas.matriz.puntajeAyuda': '符合程度如何（点击可加分）',
  'ideas.matriz.total': '总分',
  'ideas.matriz.nuevoCriterio': '新标准',
  'ideas.matriz.nuevaOpcion': '选项',
  'ideas.matriz.criterioN': '标准{n}',
  'ideas.matriz.opcionN': '选项{n}',
  'ideas.matriz.ayuda': '点击名称可以修改，点击权重可以提高该标准的重要程度，点击每个格子可以打1-5分。总分已经乘以权重计算好了。',
  'ideas.ejemplo.ver': '查看示例',
  'ideas.ejemplo.chip': '示例',
  'ideas.ejemplo.comoFunciona': '这种格式是怎么用的？',
  'ideas.guia.mental': '思维导图向四面八方展开一个主题：中心是想法，周围是大分支，细节挂在分支上。适合在确定顺序之前先把脑子里的东西倒出来。',
  'ideas.guia.arbol': '树状图像组织结构图一样，从整体到具体展开。当你手里的是能拆分成子类别的分类，而不是零散的想法时，就用它。',
  'ideas.guia.etimologia': '词源树把一个词拆解开：它的来源、含义、用法，以及同源的词有哪些。适合在头脑风暴前深入了解一个概念，或者给什么东西起名字时使用。',
  'ideas.tipo.etimologia': '词源树',
  'ideas.tipoDesc.etimologia': '拆解一个词：来源、含义、用法与同源词。',
  'ideas.guia.llaves': '括号图把整体从左到右拆分成部分——经典的大纲形式。适合拆解事物、看清它的构成。',
  'ideas.guia.circulo': '圆圈图把主题放在中心，周围环绕着你知道的一切，没有层级关系。适合探索一个概念，或者考试前复习。',
  'ideas.guia.flujo': '流程图用箭头把步骤连起来。点击一个步骤，用形状按钮把它变成开始、判断或结束：菱形是是/否的问题。',
  'ideas.guia.linea': '时间轴按日期排序：每个里程碑交替出现在线的上方和下方，细节向外延伸。里程碑开头写上年份，读起来就很清楚。',
  'ideas.guia.ciclo': '循环图把不断重复的阶段串联起来。每个阶段都从根节点添加——点击背景，这样它就不会挂在前一个阶段下面——它们会自动分布在圆周上。',
  'ideas.guia.piramide': '金字塔图把层级堆叠起来：每一层都靠下面一层支撑，所以底层是最先要打好的基础。双击层级名称即可修改。',
  'ideas.guia.venn': '韦恩图把两个集合放在一起，它们的共同点落在重叠的区域。添加前先在底部栏选择区域，或者把一个项目拖到另一个上面，它会自动移动。',
  'ideas.guia.comparacion': '对比图把两个主题分列展示，共同点放在中间。它就像表格版的韦恩图：每边要点很多时读起来更快。',
  'ideas.guia.proscontras': '每一点都有1到5的权重：选中它，用底部栏的－＋调整。每列末尾会自动求和，所以决定不再取决于“哪个列表更长”。',
  'ideas.guia.fuerzas': '力场分析着眼于一次变化：左边是推动它的力量，右边是阻碍它的力量，各自都有权重。如果右边占上风，就先解决最重的那股阻力。',
  'ideas.guia.foda': '优势和劣势是你自己的；机会和威胁来自外部。拿不准的时候，问问自己这件事是否取决于你。',
  'ideas.guia.eisenhower': '重要程度在上，紧急程度在左。“安排日程”这个象限才是真正推动进展的地方：如果它一直空着，你就是在一整天疲于救火。',
  'ideas.guia.decision': '每个分支代表一个选项及其后果。即使看起来显而易见，也要写下来：没写下来的东西，等于没法比较。',
  'ideas.guia.tier': 'S是最高，D是最低。还无法排名的先放在下方的“未分级”里，确定后再拖到对应的行。',
  'ideas.guia.ishikawa': '鱼头是问题，每根鱼骨代表一类原因（方法、设备、材料、测量……）。要找的是原因，不是解决方案：那是后面的事。',
