  'chat.manual.intro': '打开一个文件夹，点击示例就会输入到聊天框。大多数功能无需AI即可使用。',
  'chat.manual.leyenda.comando': '蓝色：指令',
  'chat.manual.leyenda.ia': '紫色：消耗一次AI调用',
  'chat.manual.leyenda.variable': '黄色：可自由修改',
  'chat.manual.nota.biblioteca': '里面住着智者（AI聊天），会把内容提炼成百科条目和主题树。',
  'chat.manual.nota.calendario': '汇总所有应用的目标和事件；它的日程还能生成AI计划（✨）。',
  'chat.manual.nota.caminos': '画好赛道和终点线后，可以和时间或助手比赛；从铁轨上车即可乘火车。',
  'chat.manual.nota.canchas': '走进球场即可开始比赛，靠近球即可操控它。',
  'chat.manual.nota.cocina': '使用AI还能识别你菜品的照片（自动估算营养并记录）。在聊天中要的食谱和饮食方案会附带图片，出现得稍慢，并按显示的点数扣费。',
  'chat.manual.nota.cuartos': '创建、重命名和整理房间。“删除”会把房间从房子里移除。',
  'chat.manual.nota.despacho': '使用AI还能附上小票照片，自动记录这笔支出。',
  'chat.manual.nota.diario': '当天的文化板块和助手推送都在应用内使用AI。',
  'chat.manual.nota.ejercicio': '使用AI：在日程里生成训练计划（✨按钮），应用内还有配图讲解动作。',
  'chat.manual.nota.entretenimiento': '桌游：贪吃蛇、俄罗斯方块、国际象棋、跳棋、数独、记忆翻牌、乒乓、冰球、西蒙、四子棋、太空、恐龙……',
  'chat.manual.nota.garage': '你骑的载具（自行车、摩托车、汽车、UFO）在“角色与载具”里。',
  'chat.manual.nota.granja': '动物：母鸡、猪、山羊、绵羊、牛和马。它们吃你在“食”里收获的东西。',
  'chat.manual.nota.hobbies': '在它的日程里可以要一份AI计划（✨）来推进项目。',
  'chat.manual.nota.huerto': '作物：胡萝卜、生菜、向日葵、番茄、玉米和南瓜。',
  'chat.manual.nota.idiomas': '里面有分级会话老师、来自聊天的卡片和按主题生成的卡片（AI）。',
  'chat.manual.nota.configuraciones':
    '编辑器“设置”标签页里的一切：语言、外观（浅色、深色、透明）、图标风格、界面主题和字体、面板玻璃质感、地图的视觉风格（普通、漫画、微缩、复古、霓虹）及其特效、通知和备份。',
  'chat.manual.aviso.configuraciones': '登录、恢复备份和删除数据都不能在聊天里完成：助手会打开对应界面，由你自己确认。',
  'chat.manual.nota.interfaz':
    '房子主题、天空背景、环境音乐和你的Wrapped年度回顾。音乐氛围：calma, festivo, nocturno, chiptune, acogedor, energia, estudio, arcade, bosque, viaje, carrera, cajita。',
  'chat.manual.nota.mapa': '方向：北、南、东、西（也可以说上、下、左、右）。',
  'chat.manual.nota.memoria': '助手会记住跨会话的信息。用回形针添加照片，或用麦克风口述；用@应用可以强制指定记录位置。',
  'chat.manual.nota.objetos': '无AI目录：台灯、椅子、桌子、植物、吉他、地毯、箱子、画、球和书。其他物件都会由AI生成3D模型并存入物品栏。2D图片用“帮我画一张……的图片”来获取，会留在聊天里。',
  'chat.manual.nota.personaje': '服装：帽子、眼镜……部位：头、躯干和腿。载具：自行车、摩托车、汽车和UFO（用Space/Shift飞行）。视角：等距、第三人称和第一人称（V键）。',
  'chat.manual.nota.sala': '使用AI时，新地点会自动定位，并以图钉显示在世界地图上。',
  'chat.manual.nota.superficies': '颜色：红、蓝、绿……或输入#开头的十六进制代码。地板材质和屋顶形状来自编辑器目录。',
  'chat.manual.nota.teclado': '用键盘玩耍的快捷键。它们不是在聊天里输入的，而是在房子里直接使用。在输入框打字或打开房间时不会生效。',
  'chat.manual.notaSeccion.apps':
    '每个应用都会用你的话记录自己的数据（用@应用可强制指定去向），说出名字就能打开对应菜单。“使用AI”的示例总会消耗一次AI调用（Pro方案或你自己的密钥）；你的自定义模板也能通过聊天记录，并按名字打开。注意：离线解析只懂西班牙语，所以中文下大多数指令都要经过AI。',
  'chat.manual.notaSeccion.mapa': '花园、农场、赛道和球场在房间之外，在3D地图上。',
